from pathlib import Path
P=Path(__file__).parent
s=P.parent.joinpath('UI_BASELINE_REMOTE.mjs').read_text()
def change(old,new):
 global s
 assert s.count(old)==1,(s.count(old),old[:120])
 s=s.replace(old,new,1)
change("const p=x?.publication,s=x?.selector,q=x?.request;", "const p=x?.publication,r=x?.release,s=x?.selector,q=x?.request;\n  if(r)return nativeExact(x,['selector','request','work_id','receipt_id','result_sha256','release'])\n   &&sameChainRequest(q,q)&&q.master_session_id===session\n   &&(nativeExact(s,['kind','request'])&&s.kind==='request'&&sameChainRequest(s.request,q)\n    ||nativeExact(s,['kind','source_revision'])&&s.kind==='staff_tick'&&s.source_revision===r.source_revision)\n   &&session==='44078c5f-7001-4129-9506-e2f34e68c8ac'&&x.work_id==='d460a7be-a3a2-4ad8-9d3b-d2e929f2947e'\n   &&UUID.test(x.receipt_id||'')&&SHA.test(x.result_sha256||'')\n   &&nativeExact(r,['source_window_id','source_revision','reason','audit_sha256'])\n   &&r.source_window_id===x.work_id&&SHA.test(r.source_revision||'')&&SHA.test(r.audit_sha256||'')\n   &&r.reason==='staff_preprovider_request_retry';")
change("x.schema_version!=='mission-journal-settlements/1'", "!['mission-journal-settlements/1','mission-journal-settlements/2'].includes(x.schema_version)")
change("||!x.items.every(i=>settlementItemValid(i,state.session_id))\n   ||new Set(x.items.map(i=>selectorKey(i.selector))).size!==x.items.length)", "||!x.items.every(i=>settlementItemValid(i,state.session_id)&&(x.schema_version==='mission-journal-settlements/2'||!i.release))\n   ||new Set(x.items.map(i=>selectorKey(i.selector)+':'+i.work_id)).size!==x.items.length)")
change("function settlementFor(items,selector,work=null){\n  return items.find(i=>sameSelector(i.selector,selector)&&(work===null||work===i.work_id))||null;\n }", "function settlementFor(items,selector,work=null,excludeWork=null){\n  const matches=items.filter(i=>sameSelector(i.selector,selector)&&(work===null||work===i.work_id)&&i.work_id!==excludeWork);\n  return matches.find(i=>i.release)||matches[0]||null;\n }")
change("const key=`${settlementSchema}:${t.user}:${item.request.master_session_id}:${selectorKey(item.selector)}`;", "const key=`${settlementSchema}:${t.user}:${item.request.master_session_id}:${selectorKey(item.selector)}${item.release?':released:'+item.work_id:''}`;")
change("||['writer_work_id','message_id','receipt_id','result_sha256'].some(k=>old.proof.publication[k]!==item.publication[k]))", "||(!!old.proof.release!==!!item.release)||(item.release\n     ?['source_window_id','source_revision','reason','audit_sha256'].some(k=>old.proof.release[k]!==item.release[k])\n     :['writer_work_id','message_id','receipt_id','result_sha256'].some(k=>old.proof.publication[k]!==item.publication[k])))")
change("const proof=settlementFor(items,selector,r.work??null);if(!proof)continue;", "const proof=settlementFor(items,selector,r.work??null,r.releasedPredecessor??null);if(!proof)continue;")
change("const journalPhase=j=>['mission-async-journal/3','mission-async-journal/4','mission-async-journal/5'].includes", "const journalPhase=j=>['mission-async-journal/3','mission-async-journal/4','mission-async-journal/5','mission-async-journal/6'].includes")
change("&&key===journalPrefix(user,session)+selectorKey(s)&&Number.isSafeInteger(j.started)", "&&key===journalPrefix(user,session)+selectorKey(s)+(Object.hasOwn(j,'released_work_id')?':released:'+j.released_work_id:'')&&Number.isSafeInteger(j.started)")
change("  if(j?.schema_version==='mission-async-journal/5'){", """  if(j?.schema_version==='mission-async-journal/6'){
   const r=j.recovery,baseKey=journalPrefix(user,session)+selectorKey(r?.selector);
   if(!nativeExact(j,['schema_version','original','recovery'])
    ||!journalPhaseValid(r,key,user,session,['user','session','selector','released_work_id','source_request_key','started','reads','lastRead','done'])
    ||r.selector.kind!=='staff_tick'||session!=='44078c5f-7001-4129-9506-e2f34e68c8ac'
    ||r.released_work_id!=='d460a7be-a3a2-4ad8-9d3b-d2e929f2947e'||!UUID.test(r.source_request_key||'')
    ||!(j.original===null||j.original?.schema_version===asyncJournalSchema
      &&journalPhaseValid(j.original,baseKey,user,session,legacyFields)&&sameSelector(j.original.selector,r.selector)))throw Error('async_journal_invalid');
  }else if(j?.schema_version==='mission-async-journal/5'){"""
)
change("selector:clone(j.selector),journalKey:key,resumeProof:j.proof_sha256??null,", "selector:clone(j.selector),journalKey:key,releasedPredecessor:j.released_work_id??null,resumeProof:j.proof_sha256??null,")
change("const proof=settlementFor(settlements,journalPhase(j).selector);", "const proof=settlementFor(settlements,journalPhase(j).selector,null,journalPhase(j).released_work_id??null);")
change("const key=journalPrefix(t.user,parent.session)+selectorKey(selector);parent.journalKey=key;", """const baseKey=journalPrefix(t.user,parent.session)+selectorKey(selector);
  let release=null;
  if(parent.tickRecoveryKey==='d460a7be-a3a2-4ad8-9d3b-d2e929f2947e'&&parent.session==='44078c5f-7001-4129-9506-e2f34e68c8ac'){
   const projection=tickStatusFor(roomState,t),proof=projection.value;
   if(!projection.applicable||!projection.valid||selector.kind!=='staff_tick'
    ||parent.session!=='44078c5f-7001-4129-9506-e2f34e68c8ac'
    ||parent.tickRecoveryKey!=='d460a7be-a3a2-4ad8-9d3b-d2e929f2947e'
    ||proof.state!=='released'||!proof.owned_by_me||!proof.can_resume
    ||proof.recovery_key!==parent.tickRecoveryKey||proof.source_revision!==selector.source_revision)
    throw Error('async_release_retry_unconfirmed');
   release=proof;
  }
  const key=baseKey+(release?':released:'+release.work_id:'');parent.journalKey=key;"""
)
change("const j={schema_version:asyncJournalSchema,user:t.user,session:parent.session,selector,started:Date.now(),reads:0,lastRead:0,done:false};\n   saveJournal(key,j);", """const phase={user:t.user,session:parent.session,selector,started:Date.now(),reads:0,lastRead:0,done:false};
   let j;
   if(release){
    const original=readJournal(baseKey,t.user,parent.session);
    if(original&&original.schema_version!==asyncJournalSchema)throw Error('async_release_original_invalid');
    j={schema_version:'mission-async-journal/6',original:original===null?null:clone(original),
     recovery:{...phase,released_work_id:release.work_id,source_request_key:release.request_key}};
   }else j={schema_version:asyncJournalSchema,...phase};
   saveJournal(key,j);"""
)
change("    j.done=true;saveJournal(key,j);const r=asyncWorks.get('journal:'+key);", "    journalPhase(j).done=true;saveJournal(key,j);const r=asyncWorks.get('journal:'+key);")
change("export const VERSION='mission-academy-flow-v4-staff-client/1-candidate';","export const VERSION='mission-academy-flow-v4-staff-client/1-c1266-request-recovery3';")
P.joinpath('mission-generic-ui.candidate.mjs').write_text(s)
print('UI candidate written')

